```javascript
const canvas = document.getElementById('myCanvas');
const ctx = canvas.getContext('2d');

// 1. 获取设备的像素比 (DPR)
const dpr = window.devicePixelRatio || 1;

// 2. 设定你期望的 CSS 显示尺寸
const displayWidth = 500;  // 你原本想要的宽度
const displayHeight = 300; // 你原本想要的高度

// 3. 将 Canvas 的实际渲染分辨率放大（乘以 DPR）
canvas.width = displayWidth * dpr;
canvas.height = displayHeight * dpr;

// 4. 通过 CSS 将 Canvas 的显示大小锁死在原本的尺寸
canvas.style.width = displayWidth + 'px';
canvas.style.height = displayHeight + 'px';

// 5. 关键一步：缩放绘图上下文，这样你后续的绘图代码（如 drawImage, fillText）不需要做任何修改
ctx.scale(dpr, dpr);

// --- 接下来像往常一样写你的绘图代码即可 ---
ctx.fillStyle = 'blue';
ctx.fillRect(10, 10, 150, 100);

ctx.font = '20px Arial';
ctx.fillStyle = 'black';
